"  useEffect(() => {
    if (selectedTable && cart && !isResettingRef.current) {
      const currentTableCart = tableCarts[selectedTable.id] || [];
      // Only sync if there is a meaningful difference
      if (currentTableCart.length !== cart.length || JSON.stringify(currentTableCart) !== JSON.stringify(cart)) {
        setTableCarts(prev => ({ ...prev, [selectedTable.id]: cart }));
      }

      // Sync table status independently of cart-saving
      const hasActiveBills = (tableBills[selectedTable.id] || []).filter(item => !item.isCancelled).length > 0;
      if (hasActiveBills) {
        if (tableStatuses[selectedTable.id] === 'AVAILABLE' || !tableStatuses[selectedTable.id]) {
          setTableStatuses(prev => ({ ...prev, [selectedTable.id]: 'SAVED' }));
        }
      } else {
        if (cart.length > 0) {
          if (tableStatuses[selectedTable.id] !== 'ORDERING') {
            setTableStatuses(prev => ({ ...prev, [selectedTable.id]: 'ORDERING' }));
          }
        } else {
          if (tableStatuses[selectedTable.id] !== 'AVAILABLE') {
            setTableStatuses(prev => ({ ...prev, [selectedTable.id]: 'AVAILABLE' }));
          }
        }
      }
    }
  }, [cart, selectedTable, tableBills]); // Removed tableCarts from dependencies to break the loop"

